/**
 *
 * -----------------------------------------------------------------------------
 *
 * Template : Virtuo Personal Portfolio HTML Template
 * Author : themes-park
 * Author URI : https://themes-park.com/ 
 *
 * -----------------------------------------------------------------------------
 *
 **/

(function ($) {
    'use strict';
    // Get the form.
    var form = $('#contact-form');
    form.attr('novalidate', true);

    // Get the messages div.
    var formMessages = $('#form-messages');

    // Set up an event listener for the contact form.
    $(form).submit(function (e) {
        // Stop the browser from submitting the form.
        e.preventDefault();

        // Custom Validation
        var hasError = false;
        var name = $('#contact-name').val();
        var email = $('#contact-email').val();
        var message = $('#contact-message').val();
        var phone = $('#contact-phone').val();
        var subject = $('#subject').val();
        var emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

        if (name) name = name.trim();
        if (email) email = email.trim();
        if (message) message = message.trim();
        if (phone) phone = phone.trim();
        if (subject) subject = subject.trim();

        // Clear previous errors
        $('.error-message').hide();
        $('.input-field').css('border-color', '');

        if (!name) {
            $('#contact-name').css('border-color', '#f06262').parent().find('.error-message').text('Please enter your name.').show();
            hasError = true;
        }
        if ($('#contact-phone').length && !phone) {
            $('#contact-phone').css('border-color', '#f06262').parent().find('.error-message').text('Please enter your phone number.').show();
            hasError = true;
        }
        if (!email || !emailPattern.test(email)) {
            $('#contact-email').css('border-color', '#f06262').parent().find('.error-message').text('Please enter a valid email address.').show();
            hasError = true;
        }
        if ($('#subject').length && !subject) {
            $('#subject').css('border-color', '#f06262').parent().find('.error-message').text('Please enter a subject.').show();
            hasError = true;
        }
        if (!message) {
            $('#contact-message').css('border-color', '#f06262').parent().find('.error-message').text('Please enter your message.').show();
            hasError = true;
        }

        if (hasError) {
            $(formMessages).removeClass('success').addClass('error').text('');
            return;
        }

        window.location.href = '404.html';
    });

    // Newsletter Validation
    $('.newsletter-form-1').attr('novalidate', true).each(function() {
        var $nform = $(this);
        var $msg = $('<div class="newsletter-msg error" style="color: var(--color-danger); font-size: 14px; margin-top: 10px; display: none;"></div>');
        $nform.after($msg);
        
        $nform.submit(function(e) {
            e.preventDefault();
            var email = $nform.find('input[type="email"]').val();
            if (email) email = email.trim();
            var emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            
            if (!email) {
                $msg.css('color', 'var(--color-danger)').text('Please enter your email address.').show();
            } else if (!emailPattern.test(email)) {
                $msg.css('color', 'var(--color-danger)').text('Please enter a valid email address.').show();
            } else {
                window.location.href = '404.html';
            }
        });
    });

})(jQuery);
;
/* --- assets/js/vendor/backtop.js --- */
$(document).ready(function () {
    "use strict";

    // Select the progress path element
    var $progressPath = $(".scrollToTop path");

    // Check if the path element is found
    if ($progressPath.length === 0) {
      console.warn("No progress path found.");
      return; // Exit the function if the path element does not exist
    }

    // Access the raw DOM element
    var progressPath = $progressPath[0];

    // Check if the element is actually available
    if (!progressPath) {
      console.error("Progress path element is null.");
      return; // Exit the function if the element is null
    }

    // Get the length of the path
    var pathLength;
    try {
      pathLength = progressPath.getTotalLength();
    } catch (e) {
      console.error("Error getting path length:", e);
      return; // Exit the function if there is an error getting the length
    }

    // Initialize progress path styles
    $(progressPath).css({
      transition: "none",
      WebkitTransition: "none",
      strokeDasharray: pathLength + " " + pathLength,
      strokeDashoffset: pathLength,
    });

    // Force browser to recalculate
    progressPath.getBoundingClientRect();

    // Set up the transition
    $(progressPath).css({
      transition: "stroke-dashoffset 10ms linear",
      WebkitTransition: "stroke-dashoffset 10ms linear",
    });

    // Function to update the progress path based on scroll
    var updateProgress = function () {
      var scroll = $(window).scrollTop();
      var height = $(document).height() - $(window).height();
      var progress = pathLength - (scroll * pathLength) / height;
      $(progressPath).css("strokeDashoffset", progress);
    };

    // Initial update
    updateProgress();

    // Update progress on scroll
    $(window).scroll(updateProgress);

    // Offset and duration for scroll-to-top button
    var offset = 50;
    var duration = 550;

    // Show or hide the progress wrap based on scroll position
    $(window).on("scroll", function () {
      if ($(this).scrollTop() > offset) {
        $(".scrollToTop").addClass("active-progress");
        $(".tmp-ready-chat").addClass("chat-visible");
      } else {
        $(".scrollToTop").removeClass("active-progress");
        $(".tmp-ready-chat").removeClass("chat-visible");
      }
    });

    // Scroll to top on progress wrap click
    $(".scrollToTop").on("click", function (event) {
      event.preventDefault();
      $("html, body").animate({ scrollTop: 0 }, duration);
      return false;
    });
  });
;
/* --- assets/js/plugins/text-type.js --- */
jQuery(document).ready(function ($) {
    //set animation timing
    var animationDelay = 2500,
        //loading bar effect
        barAnimationDelay = 3800,
        barWaiting = barAnimationDelay - 3000, //3000 is the duration of the transition on the loading bar - set in the scss/css file
        //letters effect
        lettersDelay = 50,
        //type effect
        typeLettersDelay = 150,
        selectionDuration = 500,
        typeAnimationDelay = selectionDuration + 800,
        //clip effect 
        revealDuration = 600,
        revealAnimationDelay = 1500;

    initHeadline();

    function initHeadline() {
        //insert <i> element for each letter of a changing word
        singleLetters($('.cd-headline.letters').find('b'));
        //initialise headline animation
        animateHeadline($('.cd-headline'));
    }

    function singleLetters($words) {
        $words.each(function () {
            var word = $(this),
                letters = word.text().split(''),
                selected = word.hasClass('is-visible');
            for (i in letters) {
                if (word.parents('.rotate-2').length > 0) letters[i] = '<em>' + letters[i] + '</em>';
                letters[i] = (selected) ? '<i class="in">' + letters[i] + '</i>' : '<i>' + letters[i] + '</i>';
            }
            var newLetters = letters.join('');
            word.html(newLetters).css('opacity', 1);
        });
    }

    function animateHeadline($headlines) {
        var duration = animationDelay;
        $headlines.each(function () {
            var headline = $(this);

            if (headline.hasClass('loading-bar')) {
                duration = barAnimationDelay;
                setTimeout(function () {
                    headline.find('.cd-words-wrapper').addClass('is-loading')
                }, barWaiting);
            } else if (headline.hasClass('clip')) {
                var spanWrapper = headline.find('.cd-words-wrapper'),
                    newWidth = spanWrapper.width() + 10
                spanWrapper.css('width', newWidth);
            } else if (!headline.hasClass('type')) {
                //assign to .cd-words-wrapper the width of its longest word
                var words = headline.find('.cd-words-wrapper b'),
                    width = 0;
                words.each(function () {
                    var wordWidth = $(this).width();
                    if (wordWidth > width) width = wordWidth;
                });
                headline.find('.cd-words-wrapper').css('width', width);
            };

            //trigger animation
            setTimeout(function () {
                hideWord(headline.find('.is-visible').eq(0))
            }, duration);
        });
    }

    function hideWord($word) {
        var nextWord = takeNext($word);

        if ($word.parents('.cd-headline').hasClass('type')) {
            var parentSpan = $word.parent('.cd-words-wrapper');
            parentSpan.addClass('selected').removeClass('waiting');
            setTimeout(function () {
                parentSpan.removeClass('selected');
                $word.removeClass('is-visible').addClass('is-hidden').children('i').removeClass('in').addClass('out');
            }, selectionDuration);
            setTimeout(function () {
                showWord(nextWord, typeLettersDelay)
            }, typeAnimationDelay);

        } else if ($word.parents('.cd-headline').hasClass('letters')) {
            var bool = ($word.children('i').length >= nextWord.children('i').length) ? true : false;
            hideLetter($word.find('i').eq(0), $word, bool, lettersDelay);
            showLetter(nextWord.find('i').eq(0), nextWord, bool, lettersDelay);

        } else if ($word.parents('.cd-headline').hasClass('clip')) {
            $word.parents('.cd-words-wrapper').animate({
                width: '2px'
            }, revealDuration, function () {
                switchWord($word, nextWord);
                showWord(nextWord);
            });

        } else if ($word.parents('.cd-headline').hasClass('loading-bar')) {
            $word.parents('.cd-words-wrapper').removeClass('is-loading');
            switchWord($word, nextWord);
            setTimeout(function () {
                hideWord(nextWord)
            }, barAnimationDelay);
            setTimeout(function () {
                $word.parents('.cd-words-wrapper').addClass('is-loading')
            }, barWaiting);

        } else {
            switchWord($word, nextWord);
            setTimeout(function () {
                hideWord(nextWord)
            }, animationDelay);
        }
    }

    function showWord($word, $duration) {
        if ($word.parents('.cd-headline').hasClass('type')) {
            showLetter($word.find('i').eq(0), $word, false, $duration);
            $word.addClass('is-visible').removeClass('is-hidden');

        } else if ($word.parents('.cd-headline').hasClass('clip')) {
            $word.parents('.cd-words-wrapper').animate({
                'width': $word.width() + 10
            }, revealDuration, function () {
                setTimeout(function () {
                    hideWord($word)
                }, revealAnimationDelay);
            });
        }
    }

    function hideLetter($letter, $word, $bool, $duration) {
        $letter.removeClass('in').addClass('out');

        if (!$letter.is(':last-child')) {
            setTimeout(function () {
                hideLetter($letter.next(), $word, $bool, $duration);
            }, $duration);
        } else if ($bool) {
            setTimeout(function () {
                hideWord(takeNext($word))
            }, animationDelay);
        }

        if ($letter.is(':last-child') && $('html').hasClass('no-csstransitions')) {
            var nextWord = takeNext($word);
            switchWord($word, nextWord);
        }
    }

    function showLetter($letter, $word, $bool, $duration) {
        $letter.addClass('in').removeClass('out');

        if (!$letter.is(':last-child')) {
            setTimeout(function () {
                showLetter($letter.next(), $word, $bool, $duration);
            }, $duration);
        } else {
            if ($word.parents('.cd-headline').hasClass('type')) {
                setTimeout(function () {
                    $word.parents('.cd-words-wrapper').addClass('waiting');
                }, 200);
            }
            if (!$bool) {
                setTimeout(function () {
                    hideWord($word)
                }, animationDelay)
            }
        }
    }

    function takeNext($word) {
        return (!$word.is(':last-child')) ? $word.next() : $word.parent().children().eq(0);
    }

    function takePrev($word) {
        return (!$word.is(':first-child')) ? $word.prev() : $word.parent().children().last();
    }

    function switchWord($oldWord, $newWord) {
        $oldWord.removeClass('is-visible').addClass('is-hidden');
        $newWord.removeClass('is-hidden').addClass('is-visible');
    }
});
